import{_ as e,o as a,c as r,a5 as i}from"./chunks/framework.a5no_H3L.js";const d="/unity/01-getting-started-chapter-03-editor-breakdown.png",c="/unity/01-getting-started-chapter-03-scene-gizmo.png",u=JSON.parse('{"title":"编辑器界面与工作区","description":"你已经装好了 Unity Hub 和 Unity 6.3 LTS，能打开一个新项目。读完这一篇并跟着操作，你能认清编辑器默认布局里的每个窗口是干什么的，学会在场景里导航和摆放物体，为下一步写脚本做准备。","frontmatter":{"type":"tutorial","level":"basic"},"headers":[],"relativePath":"unity/01-getting-started/chapter-03-editor-workspace.md","filePath":"unity/01-getting-started/chapter-03-editor-workspace.md"}'),s={name:"unity/01-getting-started/chapter-03-editor-workspace.md"};function n(o,t,l,p,g,h){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="编辑器界面与工作区" tabindex="-1" data-src-line="2" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">编辑器界面与工作区 <a class="header-anchor" href="#编辑器界面与工作区" aria-label="Permalink to &quot;编辑器界面与工作区&quot;">​</a></h1><p data-src-line="4" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">你已经装好了 Unity Hub 和 Unity 6.3 LTS，能打开一个新项目。读完这一篇并跟着操作，你能认清编辑器默认布局里的每个窗口是干什么的，学会在场景里导航和摆放物体，为下一步写脚本做准备。</p><h2 id="_1-打开编辑器后的默认布局" tabindex="-1" data-src-line="6" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">1. 打开编辑器后的默认布局 <a class="header-anchor" href="#_1-打开编辑器后的默认布局" aria-label="Permalink to &quot;1. 打开编辑器后的默认布局&quot;">​</a></h2><p data-src-line="8" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">新建项目后进入编辑器，屏幕被分成几个区域。Unity 的窗口都可以拖动、停靠，但第一次打开看到的是<strong>默认布局</strong>：</p><p data-src-line="10" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md"><img src="'+d+'" alt="Unity 编辑器默认布局：顶部工具栏、左侧 Hierarchy、中间 Scene 与 Game 视图、右侧 Inspector、底部 Project 窗口"></p><p data-src-line="12" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md"><em>图源：<a href="https://docs.unity3d.com/2021.1/Documentation/Manual/UsingTheEditor.html" target="_blank" rel="noreferrer">Unity 官方文档</a>，官方布局示意，Unity 6 布局结构一致</em></p><p data-src-line="14" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">下面逐个说明。先记住名字和位置，不用记每个按钮。</p><h2 id="_2-五个核心窗口" tabindex="-1" data-src-line="16" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">2. 五个核心窗口 <a class="header-anchor" href="#_2-五个核心窗口" aria-label="Permalink to &quot;2. 五个核心窗口&quot;">​</a></h2><h3 id="_2-1-hierarchy-层级窗口" tabindex="-1" data-src-line="18" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">2.1 Hierarchy（层级窗口） <a class="header-anchor" href="#_2-1-hierarchy-层级窗口" aria-label="Permalink to &quot;2.1 Hierarchy（层级窗口）&quot;">​</a></h3><p data-src-line="20" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">左侧，列出<strong>当前场景里的所有 GameObject</strong>，以树状结构表示父子关系。选中场景里的物体，它会在这里高亮；反过来在这里点击，场景里对应物体也会被选中。</p><p data-src-line="22" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">它是你组织场景的入口：新建物体、调整父子关系、删除物体都从这里开始。</p><h3 id="_2-2-scene-视图-场景视图" tabindex="-1" data-src-line="24" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">2.2 Scene 视图（场景视图） <a class="header-anchor" href="#_2-2-scene-视图-场景视图" aria-label="Permalink to &quot;2.2 Scene 视图（场景视图）&quot;">​</a></h3><p data-src-line="26" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">中间上方，是<strong>编辑世界的地方</strong>。你在这里摆放物体、调整位置、预览灯光和材质。它显示的是&quot;编辑器视角&quot;，和玩家最终看到的画面不一定一致。</p><h3 id="_2-3-game-视图-游戏视图" tabindex="-1" data-src-line="28" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">2.3 Game 视图（游戏视图） <a class="header-anchor" href="#_2-3-game-视图-游戏视图" aria-label="Permalink to &quot;2.3 Game 视图（游戏视图）&quot;">​</a></h3><p data-src-line="30" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">和 Scene 视图同一个位置，用顶部 Tab 切换。它显示的是<strong>玩家视角</strong>，即场景里摄像机看到的画面。点工具栏的 Play 按钮后，Game 视图会实时显示游戏运行画面。</p><h3 id="_2-4-inspector-检视器" tabindex="-1" data-src-line="32" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">2.4 Inspector（检视器） <a class="header-anchor" href="#_2-4-inspector-检视器" aria-label="Permalink to &quot;2.4 Inspector（检视器）&quot;">​</a></h3><p data-src-line="34" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">右侧，显示<strong>当前选中物体上挂的所有组件和属性</strong>。在 Hierarchy 或 Scene 里点一个物体，Inspector 就会列出它的 <code>Transform</code>、<code>Mesh Renderer</code>、<code>Collider</code> 等组件。改数值、加组件、删组件都在这里做。</p><p data-src-line="36" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">这是理解 Unity 组件模型最直观的地方：选中物体，看它由哪些组件拼成。</p><h3 id="_2-5-project-项目窗口" tabindex="-1" data-src-line="38" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">2.5 Project（项目窗口） <a class="header-anchor" href="#_2-5-project-项目窗口" aria-label="Permalink to &quot;2.5 Project（项目窗口）&quot;">​</a></h3><p data-src-line="40" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">底部左侧，列出<strong>项目目录里的所有资源</strong>：脚本、贴图、模型、材质、预制体等，对应磁盘上 <code>Assets/</code> 目录。你把外部资源拖进来，或在这里右键创建新资源。</p><h3 id="_2-6-console-控制台" tabindex="-1" data-src-line="42" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">2.6 Console（控制台） <a class="header-anchor" href="#_2-6-console-控制台" aria-label="Permalink to &quot;2.6 Console（控制台）&quot;">​</a></h3><p data-src-line="44" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">底部和 Project 同位置，用 Tab 切换。显示<strong>日志、警告和报错</strong>。你写的 <code>Debug.Log</code> 输出在这里，脚本报错也在这里。排错时先看 Console。</p><h2 id="_3-在-scene-视图里导航" tabindex="-1" data-src-line="46" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">3. 在 Scene 视图里导航 <a class="header-anchor" href="#_3-在-scene-视图里导航" aria-label="Permalink to &quot;3. 在 Scene 视图里导航&quot;">​</a></h2><p data-src-line="48" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">Scene 视图右上角有一个 <strong>Scene Gizmo</strong>，它显示当前视角的坐标轴方向，拖动它能快速旋转视角：</p><p data-src-line="50" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md"><img src="'+c+'" alt="Scene 视图右上角的 Scene Gizmo，显示 x/y/z 轴方向与 Persp 标签"></p><p data-src-line="52" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md"><em>图源：<a href="https://docs.unity3d.com/6000.3/Documentation/Manual/SceneViewNavigation.html" target="_blank" rel="noreferrer">Unity 官方文档</a></em></p><p data-src-line="54" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">在 Scene 视图里移动视角是最高频的操作，掌握这三招：</p><table tabindex="0"><thead data-src-line="56" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md"><tr data-src-line="56" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md"><th>操作</th><th>效果</th></tr></thead><tbody data-src-line="58" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md"><tr data-src-line="58" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md"><td>鼠标右键按住拖动</td><td>旋转视角（围绕当前焦点）</td></tr><tr data-src-line="59" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md"><td>鼠标中键按住拖动</td><td>平移视角</td></tr><tr data-src-line="60" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md"><td>滚动滚轮</td><td>拉近拉远</td></tr></tbody></table><p data-src-line="62" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">选不中物体时，先点一下物体再操作；找不到物体时，在 Hierarchy 里双击它的名字，视角会自动聚焦过去。</p><h2 id="_4-变换工具-移动、旋转、缩放" tabindex="-1" data-src-line="64" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">4. 变换工具：移动、旋转、缩放 <a class="header-anchor" href="#_4-变换工具-移动、旋转、缩放" aria-label="Permalink to &quot;4. 变换工具：移动、旋转、缩放&quot;">​</a></h2><p data-src-line="66" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">工具栏左侧有一排工具，对应快捷键 Q/W/E/R/T：</p><ul data-src-line="68" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md"><li data-src-line="68" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md"><strong>W（Move）</strong>：移动物体，显示三个轴向的箭头，拖动箭头沿轴移动。</li><li data-src-line="69" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md"><strong>E（Rotate）</strong>：旋转物体，显示三个圆环。</li><li data-src-line="70" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md"><strong>R（Scale）</strong>：缩放物体，显示三个轴向的方块。</li><li data-src-line="71" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md"><strong>Q（Hand）</strong>：平移视图（和鼠标中键一样）。</li></ul><p data-src-line="73" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">在 Scene 里选中一个物体后按 W，拖动物体身上的箭头，同时在 Inspector 里观察 <code>Transform</code> 的 Position 数值变化，就能理解&quot;场景里的操作 = 修改 Transform 组件&quot;。</p><h2 id="_5-动手验证" tabindex="-1" data-src-line="75" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">5. 动手验证 <a class="header-anchor" href="#_5-动手验证" aria-label="Permalink to &quot;5. 动手验证&quot;">​</a></h2><p data-src-line="77" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">按下面的步骤走一遍，确认你对窗口的理解正确：</p><ol data-src-line="79" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md"><li data-src-line="79" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">在 Hierarchy 顶部空白处右键，选择 <strong>3D Object → Cube</strong>，场景里出现一个立方体。</li><li data-src-line="80" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">在 Inspector 里看它：有 <code>Transform</code>、<code>Mesh Renderer</code>、<code>Box Collider</code> 三个组件。</li><li data-src-line="81" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">按 W，在 Scene 里拖动立方体的箭头，看 Inspector 里 Position 变化。</li><li data-src-line="82" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">按工具栏的 <strong>Play</strong> 按钮（顶部中间的三角形），Game 视图亮起，显示摄像机看到的画面。</li><li data-src-line="83" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">再按一次 Play 退出运行。</li></ol><p data-src-line="85" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">如果第 4 步 Game 视图是黑的或看不到立方体，多半是摄像机没对准物体：在 Hierarchy 里选中 <code>Main Camera</code>，按 F 让视角聚焦，或用 W 移动立方体到摄像机前方。</p><p data-src-line="87" data-src-file="unity/01-getting-started/chapter-03-editor-workspace.md">走通这个流程后，你已经会&quot;创建物体 → 改 Transform → 运行&quot;这条最基本的操作链。下一步把脚本加进去，让物体自己动起来：<a href="./chapter-04-first-project.html">第一个项目：场景、GameObject 与组件</a>。</p>',38)])])}const y=e(s,[["render",n]]);export{u as __pageData,y as default};
